@js:
var result = [];
var push = function(title, url, size) {
    result.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: size
        }
    });
};
var regions = [
    {name: '全部', code: '26'},
    {name: '韩漫', code: 'Kc'},
    {name: '日漫', code: 'Jc'},
    {name: '中漫', code: 'Cc'},
    {name: '欧美漫', code: 'Ec'},
    {name: '其他', code: 'Oc'}
];
var types = [
    'All', '恋爱', '冒险', '生活', '校园', '热血', '魔法', '悬疑', '科幻',
    '运动', '都市', '耽美', '搞笑', '单女主', '纯爱', '总裁', '奇幻', '恐怖',
    '灵异', '异能', '穿越', '剧情', '古风', '言情', '玄幻', '复仇', '多女主',
    '霸总', '虐恋', '青春', '真人', '重生', '甜宠', '游戏竞技', '家庭', 'BL',
    '民国', '同人', '系统', '爱情', '美人', '喜剧', '纯真', '腹黑', '财阀',
    '后宫', '战争', '修真', '其他'
];
for (var r = 0; r < regions.length; r++) {
    var region = regions[r];
    for (var t = 0; t < types.length; t++) {
        var type = types[t];
        var isAll = (t === 0);
        var base;
        if (isAll) {
            base = '/type/' + region.code;
        } else {
            var encodedType = (type === 'All' || type === 'BL') ? type : encodeURIComponent(type);
            base = '/type/' + region.code + '--' + encodedType;
        }
        var url;
        if (isAll) {
            url = '@js:var base="' + base + '";if(page==1){base+"-----.html";}else{base+"---"+page+"--.html";}';
        } else {
            url = '@js:var base="' + base + '";if(page==1){base+"---.html";}else{base+"-"+page+"--.html";}';
        }
        var title;
        if (isAll) {
            title = '📌 ' + region.name + '·全部';
        } else {
            title = region.name + '·' + type;
        }
        var size = isAll ? 1 : 0.35;
        push(title, url, size);
    }
}
JSON.stringify(result);

ruleBookInfo.intro:
@js:
var names = [];
var tm = result.match(/data-toggle="tab"[^>]*>([^<]+)</g);
if (tm) {
    for (var i = 0; i < tm.length; i++) {
        var mm = tm[i].match(/>([^<]+)</);
        if (mm) names.push(mm[1]);
    }
}
var n = names.length;
if (n === 0) {
    n = (result.match(/<ul class="stui-content__playlist/g) || []).length;
    for (var z = 0; z < n; z++) {
        names.push('线路' + (z + 1));
    }
}
var xu = '0';
try {
    var cv = book.getVariable('custom');
    if (cv != null && cv != '') {
        xu = String(cv);
    }
} catch(e) {}
if (xu == '0' || xu == '') {
    var ov = String(book.variable || '');
    if (ov != '') {
        xu = ov;
    }
}
var list = '';
for (var i2 = 0; i2 < names.length; i2++) {
    list += '◖' + i2 + '◗' + names[i2] + ' ';
}
var lineInfo = '【线路列表】' + list.trim() + '\n当前来源◖' + xu + '◗\n（右上角书籍变量填 0-' + (n - 1) + ' 刷新切换线路）';
var desc = '';
var dcMatch = result.match(/<span class="detail-content" style="display: none;">([\s\S]*?)<\/span>/);
if (dcMatch) {
    desc = dcMatch[1].trim();
}
if (!desc) {
    var dsMatch = result.match(/<span class="detail-sketch">([\s\S]*?)<\/span>/);
    if (dsMatch) {
        desc = dsMatch[1].trim();
    }
}
if (!desc) {
    desc = java.getString('meta[name="description"]@content') || '';
}
lineInfo + '\n\n📖 简介：' + desc;

ruleContent.content:
@js:
var um = result.match(/"url":"([0-9a-f]+)"/);
var enc = um ? um[1] : '';
var out = '';
if (enc) {
  try {
    var resp = java.get('https://image.kalaimg.top/play/min/' + enc, {Referer: 'https://www.kalamanhua.com/'});
    var minHtml = String(resp.body());
    var d1 = minHtml.indexOf('var d="');
    var b64 = '';
    if (d1 >= 0) { var d2 = minHtml.indexOf('"', d1 + 7); if (d2 > d1) { b64 = minHtml.substring(d1 + 7, d2); } }
    var k1 = minHtml.indexOf('k=[');
    var k = [];
    if (k1 >= 0) { var k2 = minHtml.indexOf(']', k1 + 3); if (k2 > k1) { var kp = minHtml.substring(k1 + 3, k2).split(','); for (var t = 0; t < kp.length; t++) { k.push(parseInt(kp[t])); } } }
    if (b64 && k.length > 0) {
      var bytes = java.base64DecodeToByteArray(b64);
      var dec = '';
      for (var i = 0; i < bytes.length; i++) {
        dec += String.fromCharCode((bytes[i] & 0xff) ^ k[i % k.length]);
      }
      var imgs = dec.match(/data-src="\/image\/index\/[^"]+"/g);
      if (imgs) {
        for (var j = 0; j < imgs.length; j++) {
          var src = imgs[j].replace(/data-src="/, '').replace(/"$/, '');
          out += '<img src="https://image.kalaimg.top' + src + ',{"headers":{"Referer":"https://www.kalamanhua.com/"}}">';
        }
      }
    }
  } catch(e) {}
}
out;

