        "method": "POST"
    }),
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: size
    }
});

// typeId名称映射
var types = ["", "国产", "日韩", "欧美", "港台", "电影", "里番"];
// 全部tag列表（含空=全部）
