exploreUrl:
@js:
const sort=[];
const base="/Service";
const styleTitle={layout_flexGrow:1,layout_flexBasisPercent:1
};
const styleItem={layout_flexGrow:0,layout_flexBasisPercent:0.29};
const states=[
	{title:"完本",value:1},
	{title:"连载",value:0}
];
const sortRules=[
	{title:"入库",value:0},
	{title:"热门",value:20},
	{title:"点击",value:4},
	{title:"更新",value:12},
	{title:"收藏",value:14}
];
const categories=[
	//["仙侠","xianxia"],
	//["网游","wangyou"],
	//["惊悚","jingsong"],
	//["灵异","lingyi"],
	//["言情","yanqing"],
	//["耽美","danmei"],
	//["女尊","nvzun"],
	["都市","dushi"],
	["乡土","xiangtu"],
	["官场","guanchang"],
	["校园","xiaoyuan"],
	["异能","yineng"],
	["历史","lishi"],
	["古典","gudian"],
	["武侠","wuxia"],
	["穿越","chuanyue"],
	["同人","tongren"],
	["单篇","danpian"]
];
function buildUrl(state,sortValue,parentclassid){
	const params=`{\\"Method\\":\\"book_byshuyuansearch\\",\\"Parameters\\":{\\"index\\":\\"{{page-1}}\\",\\"state\\":${state},\\"sort\\":${sortValue},\\"parentclassid\\":\\"${parentclassid}\\"}}`;
	return `${base},{"body":"requestData=${params}","method":"POST"}`;
};
sortRules.forEach(rule=>{
	sort.push({
		title:rule.title,
		url:buildUrl(0,rule.value,0),
		style:styleItem
	});
});
states.forEach(state=>{
	sort.push({
		title:`🌀${state.title}🌀`,
		url:"",
		style:styleTitle
	});
	sortRules.slice(0,3).forEach(sortRule=>{
		sort.push({
			title:`${sortRule.title}`,
			url:buildUrl(state.value,sortRule.value,0),
			style:styleTitle
		});
		categories.forEach(([title,uri])=>{
			sort.push({
				title:title,
				url:buildUrl(state.value,sortRule.value,uri),
				style:styleItem
			});
		});
	});
});
//java.log(JSON.stringify(sort));
JSON.stringify(sort)

ruleToc.chapterList:
ol li
@js:
var list=[],links=result.select("a"),regex=/(\w+-\w+)(?==")/g;
for (i=0;i<links.length;i++){
	link=links[i];
	aAttrs=String(link).match(regex);
	var text='',decUrl='';
	for (key of aAttrs){
		value=link.attr(key);
		value.includes("L2J")?decUrl=java.base64Decode(value):text=value.trim()
	}
	liAttrs=String(result[i]).match(regex);
	list.push({
		text:text,
		href:decUrl,
		num:result[i].attr(liAttrs[1])
	});
}
list.sort((a,b)=>a.num-b.num)

